      'w-kh1': { title:"Гонец", subject:"Всадник, везущий весть по Семиречью, написан с натуры, увиденной на экспедиционных маршрутах.", making:"Хлудов служил рисовальщиком в геологических и ботанических экспедициях; оттуда и сюжеты." },
      'w-ai-may': { title:"Первомай", subject:"Первое мая над Алма-Атой: толпа на склоне, шары, красные флаги и строительные краны, а верхнюю половину квадратного холста занимает Заилийский Алатау.", making:"Большой квадратный холст 1960 года — под праздником настоящий сюжет — сам город, ещё строящийся." },
      'w-ai-har': { title:"На уборке", subject:"Работник на уборке, написанный с близкого расстояния, за ним поле и постройка.", making:"Акварель на бумаге, 1967 — лист сделан быстро и оставлен прозрачным." },
      'w-ai-zha': { title:"Жайляу", subject:"Отара поднимается на джайляу красным ущельем, чабаны отдыхают у ближнего края.", making:"Без даты. Летовка в горах — постоянный сюжет пейзажей Исмаилова." },
      'w-ai-gor': { title:"Ущелье со стадом", subject:"Узкое ущелье сверху, снежная вершина за ним и стоянка со стадом на дне долины.", making:"Без даты. Вертикальный формат, необычный для пейзажа этих лет." },
      'w-ai-ala': { title:"Совхоз Алатау, Талгарский район", subject:"Совхоз Алатау в Талгарском районе — небольшой этюд, сделанный на месте.", making:"Картон, масло, 16 × 11 см. Рабочий этюд, а не выставочная вещь." },
      'w-ai-mou': { title:"Горы", subject:"Предгорья весной: хребет сиреневый под снегом, одинокое дерево на первом плане.", making:"Холст, масло, 20 × 31 см, 1990 — написана в самом конце рабочей жизни художника." },
      'w-ka1': { title:"Турксиб", subject:"Строительство Турксиба, написанное, когда линия была ещё новой. Поезд мал на фоне степи: сюжет — страна, которую пересекает дорога, а не сама стройка.", making:"Кастеев работал прозрачной акварелью, в дороге, в те годы, когда у республики ещё не было собственной традиции станковой живописи." },
      'w-kl1': { title:"Фантастический пейзаж (с красными скалами)", subject:"Придуманный пейзаж в высоком нереальном цвете, не отвечающий ни заказу, ни программе.", making:"Калмыков писал непрерывно помимо театральной работы; эта часть наследия впервые была показана только после его смерти." },
      'w-ma1': { title:"Моя юрта", subject:"Внутренность юрты прочитана как плоский узор: войлок, орнамент и фигура лежат в одной плоскости и весят одинаково.", making:"Написана после возвращения Мамбеева из Ленинграда; её обычно называют работой, открывшей декоративный «национальный стиль» шестидесятых." },
      'w-ke1': { title:"Ловля лошади" },
      'w-te1': { title:"На земле дедов" },
      'w-is1': { title:"Портрет Куляш Байсеитовой в роли Кыз-Жибек", subject:"Куляш Байсеитова в заглавной партии оперы «Кыз-Жибек» — портрет артистки в костюме, фронтальный и церемониальный.", making:"Исмаилова писала его, работая внутри самого театра; костюм передан с аппетитом сценографа, а не наблюдателя." },
      'w-ai1': { title:"Счастье", subject:"Молодая семья, монументальная и фронтальная, палитра сведена к земле и небу.", making:"Айтбаеву было двадцать восемь. На следующий год холст показали в Москве, и он сделал имя художника за один сезон." },
      'w-dz1': { title:"Женщины моей Родины", subject:"Женщины родного края художника, удержанные неподвижно в неглубоком декоративном пространстве.", making:"Написана на исходе оттепели, когда национальный сюжет можно было показать современным языком без оговорок." },
      'w-ka2': { title:"Медеу", subject:"Горное ущелье над Алма-Атой — воскресное место всего города задолго до того, как каток сделал Медеу известным.", making:"Поздняя акварель, написанная со склона, а не с фотографии: высокий горизонт, фигуры оставлены мелкими." },
      'w-sa1': { title:"Чабан" },
